"use strict";
import { useMemo, useCallback } from "react";
import { useAccount } from "hooks/useAccount";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { useContract } from "hooks/useContract";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useAbstractV2ClaimFees } from "./useAbstractV2ClaimFees";
import { UniverseChainId } from "uniswap/src/features/chains/types";
export function useTradingFeeRewards(position) {
  const { address, chainId } = useAccount();
  const contracts = chainId ? getAbstractContracts(chainId) : null;
  const positionManager = useContract(
    contracts?.nonfungiblePositionManager,
    NonfungiblePositionManagerJson.abi,
    true,
    chainId
  );
  const isV2Position = position?.version === ProtocolVersion.V2;
  const v2FeeCollection = useAbstractV2ClaimFees({
    poolAddress: position?.poolId || "",
    userAddress: address || "",
    chainId: chainId || UniverseChainId.Mainnet,
    enabled: isV2Position && !!position?.poolId && !!address
  });
  const feeData = useMemo(() => {
    if (!position) {
      return {
        token0Fees: "0",
        token1Fees: "0",
        totalFeesUSD: "N/A",
        // Show N/A for USD on testnet
        canCollect: false,
        isLoading: false
      };
    }
    if (isV2Position) {
      const hasCollectableFees2 = parseFloat(v2FeeCollection.pendingFees0) > 0 || parseFloat(v2FeeCollection.pendingFees1) > 0;
      return {
        token0Fees: parseFloat(v2FeeCollection.pendingFees0).toFixed(6),
        token1Fees: parseFloat(v2FeeCollection.pendingFees1).toFixed(6),
        totalFeesUSD: "N/A",
        canCollect: hasCollectableFees2,
        isLoading: v2FeeCollection.isLoading
      };
    }
    const token0UncollectedFees = position.token0UncollectedFees || "0";
    const token1UncollectedFees = position.token1UncollectedFees || "0";
    const token0Decimals = position.currency0Amount.currency.decimals;
    const token1Decimals = position.currency1Amount.currency.decimals;
    const token0Fees = parseFloat(token0UncollectedFees) > 0 ? (parseFloat(token0UncollectedFees) / Math.pow(10, token0Decimals)).toFixed(6) : "0";
    const token1Fees = parseFloat(token1UncollectedFees) > 0 ? (parseFloat(token1UncollectedFees) / Math.pow(10, token1Decimals)).toFixed(6) : "0";
    const hasCollectableFees = parseFloat(token0UncollectedFees) > 0 || parseFloat(token1UncollectedFees) > 0;
    const canCollect = hasCollectableFees && Boolean(position.tokenId && positionManager);
    return {
      token0Fees,
      token1Fees,
      totalFeesUSD: "N/A",
      // Show N/A for USD on testnet
      canCollect,
      isLoading: false
    };
  }, [position, positionManager, isV2Position, v2FeeCollection]);
  const collectFees = useCallback(async () => {
    if (!position || !address) {
      throw new Error("Missing required data for fee collection");
    }
    try {
      if (position.version === ProtocolVersion.V2) {
        console.log("Collecting fees for V2 position:", position.poolId);
        const result = await v2FeeCollection.claimFees();
        if (!result.success) {
          throw new Error(v2FeeCollection.error || "Failed to claim V2 fees");
        }
        console.log("V2 fees collected successfully!");
        return { hash: result.hash };
      } else if (position.version === ProtocolVersion.V3) {
        if (!positionManager) {
          throw new Error("Position manager not available");
        }
        const v3Position = position;
        if (!v3Position.tokenId) {
          throw new Error("V3 position missing tokenId");
        }
        console.log("Collecting fees for V3 position:", v3Position.tokenId);
        const MAX_UINT128 = "340282366920938463463374607431768211455";
        const collectParams = {
          tokenId: v3Position.tokenId,
          recipient: address,
          amount0Max: MAX_UINT128,
          amount1Max: MAX_UINT128
        };
        const tx = await positionManager.collect(collectParams);
        console.log("Fee collection transaction:", tx.hash);
        await tx.wait();
        console.log("Fees collected successfully!");
        return tx;
      } else {
        throw new Error("Unknown position version");
      }
    } catch (error) {
      console.error("Error collecting fees:", error);
      throw error;
    }
  }, [position, positionManager, address, v2FeeCollection]);
  return {
    ...feeData,
    collectFees
  };
}
export function useAllTradingFeeRewards(positions = []) {
  return useMemo(() => {
    if (positions.length === 0) {
      return {
        totalToken0Fees: "0",
        totalToken1Fees: "0",
        totalFeesUSD: "0",
        positionsWithFees: 0,
        canCollectAll: false,
        isLoading: false
      };
    }
    return {
      totalToken0Fees: "0",
      // Sum of all token0 fees across positions
      totalToken1Fees: "0",
      // Sum of all token1 fees across positions  
      totalFeesUSD: "0",
      // Total USD value of all fees
      positionsWithFees: 0,
      // Count of positions with collectible fees
      canCollectAll: false,
      // True if any position has fees to collect
      isLoading: false
    };
  }, [positions]);
}
